import React from 'react';
import { Loader2 } from 'lucide-react';

interface WidgetDataGuardProps {
  loading: boolean;
  error: string | null;
  data: unknown;
  children: React.ReactNode;
}

/**
 * Guard compartido para widgets: muestra spinner en loading y lanza error
 * (capturado por WidgetErrorBoundary) si hay fallo o datos nulos.
 */
export const WidgetDataGuard: React.FC<WidgetDataGuardProps> = ({ loading, error, data, children }) => {
  if (loading) {
    return (
      <div className="w-full h-full flex items-center justify-center">
        <Loader2 className="w-6 h-6 text-blue-500 animate-spin" />
      </div>
    );
  }

  // Lanzar error de fetch antes de verificar data null — evita ErrorBoundary prematuro durante carga inicial
  if (error) {
    throw new Error(error);
  }

  if (data == null) {
    // Sin datos y sin error: puede ser estado inicial o respuesta vacía del endpoint
    return (
      <div className="w-full h-full flex items-center justify-center text-sm text-gray-400">
        Sin datos disponibles
      </div>
    );
  }

  return <>{children}</>;
};
